def check_git_safety(task: dict) -> tuple[bool, str]:
    """Returns (blocked, reason). blocked=True means unsafe git op."""
    step_actions = [s.get("action", "") for s in task.get("steps", [])]
    for idx, step in enumerate(task.get("steps", [])):
