        # 2. data/task_queue.json for existing DONE/DISPATCHED entry with same idempotency_key
        try:
            all_tasks = self.queue.list_all()
            for t in all_tasks:
                if t.idempotency_key == spec.idempotency_key and t.status in ("DONE", "DISPATCHED"):
