        if raw_status == "in_progress":
            raw_status = "running"
        elif raw_status == "completed":
            raw_status = "done"

        try:
            return cls(
                id          = data.get("id", str(uuid.uuid4())),
                description = data["description"],
                goal        = data.get("goal", data.get("description", "")),
                plan_steps  = data.get("plan_steps", []),
