def scan_banned_tools(hours: int = 8) -> list[dict]:
    """Scan gemini_scratch.jsonl for banned tool patterns."""
    if not SCRATCH.exists():
        return []

    cutoff = datetime.now(tz=timezone.utc) - timedelta(hours=hours)
    hits = []

    for raw in SCRATCH.read_text(errors="replace").splitlines():
        raw = raw.strip()
        if not raw:
            continue
        try:
            e = json.loads(raw)
            ts_str = e.get("t", "")
            if not ts_str:
                continue
            ts = datetime.fromisoformat(ts_str)
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=timezone.utc)
            if ts < cutoff:
                continue
            detail = e.get("detail", "")
            for pattern, alt in BANNED_PATTERNS:
                if pattern.lower() in detail.lower():
                    hits.append({
                        "ts": ts_str,
                        "detail": detail,
                        "pattern": pattern.strip(),
                        "alternative": alt,
                    })
        except Exception:
            continue

    return hits
