def get_secret(key: str, default: Optional[str] = None) -> Optional[str]:
    """Retrieve config variables from the vault."""
    # If running under pytest, prioritize direct os.environ lookup to support env patching
    if "pytest" in sys.modules:
        val = os.environ.get(key)
        if val is not None:
            return val
        return _SECRETS.get(key, default)

    vault = CredentialVault.get_instance()
    # If the singleton hasn't been initialized with secrets yet, read from _SECRETS
    if not vault._secrets and _SECRETS:
        vault.initialize(_SECRETS)

    val = vault.get_secret(key)
    if val is not None:
        return val

    if key in _SECRETS:
        return _SECRETS[key]

    return default
